.nav a[aria-current="page"] {
  background: rgba(0,130,74,0.10);
  border: 1px solid rgba(0,130,74,0.20);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 999px;
  border: 1px solid var(--gb-border);
  background: var(--gb-surface);
  box-shadow: 0 10px 24px rgba(20, 32, 22, 0.06);
  font-weight: 700;
  letter-spacing: -0.01em;
  cursor: pointer;
  user-select: none;
}
.btn:hover { transform: translateY(-1px); box-shadow: var(--gb-shadow-sm); }
.btn:active { transform: translateY(0); }
.btn:focus-visible { outline: 3px solid rgba(0,130,74,0.30); outline-offset: 2px; }

.btn-primary {
  border-color: rgba(0,130,74,0.25);
  background: linear-gradient(135deg, rgba(0,130,74,0.95), rgba(0,130,74,0.80));
  color: white;
  box-shadow: 0 18px 40px rgba(0,130,74,0.22);
}
.btn-primary:hover { box-shadow: 0 22px 50px rgba(0,130,74,0.28); }

.btn-ghost {
  background: transparent;
  box-shadow: none;
