main { padding: 26px 0 46px; }

.h1 {
  font-family: var(--font-display);
  font-weight: 850;
  letter-spacing: -0.03em;
  line-height: 1.05;
}
.h2 {
  font-family: var(--font-display);
  font-weight: 850;
  letter-spacing: -0.02em;
  line-height: 1.12;
}
.lead { color: rgba(20,32,22,0.75); font-size: 16px; }

.kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(243,206,161,0.45);
  border: 1px solid rgba(50,70,47,0.18);
  color: var(--gb-forest);
  font-weight: 750;
  letter-spacing: -0.01em;
  font-size: 12px;
}

.grid {
  display: grid;
  gap: 18px;
}

.card {
  background: var(--gb-surface);
  border: 1px solid var(--gb-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--gb-shadow-sm);
  overflow: hidden;
}
.card-pad { padding: 18px; }

.hero {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 18px;
  align-items: stretch;
}

.hero-media {
  min-height: 320px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  border: 1px solid var(--gb-border);
  box-shadow: var(--gb-shadow-sm);
  background:
    radial-gradient(700px 380px at 20% 20%, rgba(243,206,161,0.70), transparent 55%),
    radial-gradient(800px 420px at 80% 0%, rgba(0,130,74,0.22), transparent 60%),
    linear-gradient(135deg, rgba(50,70,47,0.15), rgba(20,32,22,0.03));
}
.hero-media .photo {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(420px 260px at 55% 55%, rgba(255,255,255,0.55), transparent 65%),
    url('assets/hero-placeholder.svg');
  background-size: cover;
  background-position: center;
  opacity: 0.95;
}

.hero-content {
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
}

.pills { display: flex; flex-wrap: wrap; gap: 10px; }
.pill {
  border: 1px solid rgba(0,130,74,0.25);
  background: rgba(0,130,74,0.08);
  color: var(--gb-forest);
  padding: 8px 10px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin: 8px 0 12px;
}
.section-head .title { margin: 0; }
.section-head .meta { color: rgba(20,32,22,0.70); font-size: 14px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 18px;
}

.feature {
  grid-column: span 6;
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  min-height: 240px;
}

.feature .media {
  min-height: 240px;
  background: linear-gradient(135deg, rgba(50,70,47,0.20), rgba(243,206,161,0.18));
  position: relative;
}
.feature .media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: url('assets/photo-placeholder.svg');
  background-size: cover;
  background-position: center;
  opacity: 0.95;
}
.feature .content { padding: 18px; display: flex; flex-direction: column; gap: 10px; }
.feature .content p { margin: 0; color: rgba(20,32,22,0.75); }

.two-up {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.banner {
  border-radius: var(--radius-lg);
  border: 1px solid rgba(0,130,74,0.18);
  background:
    radial-gradient(900px 380px at 10% 0%, rgba(0,130,74,0.22), transparent 55%),
    radial-gradient(900px 380px at 95% 10%, rgba(243,206,161,0.55), transparent 55%),
    linear-gradient(135deg, rgba(255,255,255,0.86), rgba(255,255,255,0.70));
  box-shadow: var(--gb-shadow-sm);
  overflow: hidden;
}
.banner-inner { padding: 18px; display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 18px; align-items: center; }
.banner h3 { margin: 0; font-family: var(--font-display); letter-spacing: -0.02em; }
.banner p { margin: 6px 0 0; color: rgba(20,32,22,0.72); }

/* Menu layout */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 18px;
  align-items: start;
}
.sidebar {
  position: sticky;
  top: 86px;
}
.sidebar .card-pad { padding: 16px; }
.sidebar h3 { margin: 0 0 10px; font-family: var(--font-display); letter-spacing: -0.02em; }
.sidebar .group { margin-top: 14px; }
.sidebar .group-title { font-size: 12px; font-weight: 850; color: rgba(20,32,22,0.55); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 8px; }
.sidebar a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 14px;
}
.sidebar a:hover { background: rgba(0,130,74,0.07); text-decoration: none; }
.sidebar a.active { background: rgba(0,130,74,0.11); border: 1px solid rgba(0,130,74,0.20); }
.sidebar .count { font-size: 12px; color: rgba(20,32,22,0.55); }

.category {
  scroll-margin-top: 110px;
}
.category + .category { margin-top: 18px; }
.category .card-pad { padding: 18px; }
.category h2 { margin: 0 0 10px; }
.item-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.item {
  border-radius: var(--radius-md);
  border: 1px solid var(--gb-border);
  background: linear-gradient(135deg, rgba(255,255,255,0.9), rgba(251,250,247,0.9));
  padding: 12px;
  box-shadow: 0 10px 22px rgba(20,32,22,0.05);
}
.item h4 { margin: 0; font-size: 14px; letter-spacing: -0.01em; }
.item p { margin: 6px 0 0; color: rgba(20,32,22,0.65); font-size: 13px; }

/* Tabs */
.tabs {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.tab {
  padding: 10px 12px;
  border-radius: 999px;
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.75);
  cursor: pointer;
  font-weight: 800;
  letter-spacing: -0.01em;
  font-size: 13px;
}
.tab[aria-selected="true"] {
  background: rgba(0,130,74,0.12);
  border-color: rgba(0,130,74,0.25);
}
.tab:focus-visible { outline: 3px solid rgba(0,130,74,0.30); outline-offset: 2px; }

.tab-panel {
  margin-top: 14px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.8);
  box-shadow: 0 14px 34px rgba(20,32,22,0.07);
  padding: 16px;
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
}
.carousel-track {
  display: flex;
  gap: 14px;
  transition: transform 380ms cubic-bezier(0.2, 0.8, 0.2, 1);
  will-change: transform;
  padding: 2px;
}
.carousel-card {
  min-width: 240px;
  max-width: 240px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  background: linear-gradient(135deg, rgba(0,130,74,0.12), rgba(243,206,161,0.24));
  box-shadow: 0 12px 26px rgba(20,32,22,0.08);
  overflow: hidden;
}
.carousel-card .thumb {
  height: 132px;
  background: url('assets/gift-placeholder.svg');
  background-size: cover;
  background-position: center;
}
.carousel-card .label { padding: 12px; font-weight: 850; letter-spacing: -0.01em; }

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 999px;
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.85);
  box-shadow: var(--gb-shadow-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.carousel-nav:hover { background: rgba(255,255,255,0.95); }
.carousel-nav:focus-visible { outline: 3px solid rgba(0,130,74,0.30); outline-offset: 2px; }
.carousel-nav.prev { left: 10px; }
.carousel-nav.next { right: 10px; }

/* Store locator */
.locator-layout { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: 18px; align-items: start; }
.map {
  min-height: 440px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  overflow: hidden;
  background:
    radial-gradient(520px 240px at 30% 30%, rgba(0,130,74,0.18), transparent 60%),
    radial-gradient(560px 260px at 80% 20%, rgba(243,206,161,0.45), transparent 65%),
    url('assets/map-placeholder.svg');
  background-size: cover;
  background-position: center;
  box-shadow: var(--gb-shadow-sm);
  position: relative;
}
.map .chip {
  position: absolute;
  left: 16px;
  top: 16px;
}

.input {
  width: 100%;
  padding: 12px 12px;
  border-radius: 14px;
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.85);
  font: inherit;
}
.input:focus { outline: 3px solid rgba(0,130,74,0.25); border-color: rgba(0,130,74,0.28); }

.suggestions {
  margin-top: 8px;
  border-radius: 14px;
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.96);
  overflow: hidden;
}
.suggestions button {
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  border: 0;
  background: transparent;
  cursor: pointer;
  font: inherit;
}
.suggestions button:hover { background: rgba(0,130,74,0.07); }

.toggle-row { display: flex; flex-wrap: wrap; gap: 10px; }

.segment {
  display: inline-flex;
  border-radius: 999px;
  border: 1px solid var(--gb-border);
  overflow: hidden;
  background: rgba(255,255,255,0.80);
}
.segment button {
  padding: 10px 12px;
  border: 0;
  background: transparent;
  cursor: pointer;
  font-weight: 850;
  letter-spacing: -0.01em;
}
.segment button[aria-pressed="true"] { background: rgba(0,130,74,0.12); }
.segment button:focus-visible { outline: 3px solid rgba(0,130,74,0.30); outline-offset: -3px; }

.filter-panel {
  margin-top: 12px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.85);
  padding: 12px;
}
.filter-panel[hidden] { display: none; }

.store-list { display: grid; gap: 12px; }
.store {
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.90);
  padding: 12px;
  box-shadow: 0 12px 26px rgba(20,32,22,0.06);
}
.store h4 { margin: 0; letter-spacing: -0.01em; }
.store .meta { margin-top: 6px; color: rgba(20,32,22,0.70); font-size: 13px; }
.store .tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.tag { padding: 6px 8px; border-radius: 999px; background: rgba(243,206,161,0.42); border: 1px solid rgba(50,70,47,0.16); font-weight: 800; font-size: 12px; }

/* Footer */
.site-footer {
  border-top: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.70);
  backdrop-filter: blur(10px);
}
.footer-inner { padding: 26px 0; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
.footer-section {
  border-radius: var(--radius-md);
  border: 1px solid rgba(20,32,22,0.06);
  background: rgba(255,255,255,0.70);
  overflow: hidden;
}
.footer-head {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px;
  border: 0;
  background: transparent;
  cursor: default;
  text-align: left;
}
.footer-head .label { font-weight: 900; letter-spacing: -0.01em; }
.footer-head .chev { display: none; }
.footer-links { padding: 0 12px 12px; display: grid; gap: 8px; }
.footer-links a { color: rgba(20,32,22,0.70); font-weight: 650; font-size: 13px; }

.footer-bottom { margin-top: 18px; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 10px; color: rgba(20,32,22,0.70); font-size: 13px; }

/* Cookie banner */
.cookie {
  position: fixed;
  left: 18px;
  right: 18px;
  bottom: 18px;
  z-index: 100;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gb-border);
  background: rgba(255,255,255,0.92);
  box-shadow: var(--gb-shadow);
}
.cookie-inner { padding: 14px; display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: center; }
.cookie p { margin: 0; color: rgba(20,32,22,0.75); font-size: 13px; }

/* Responsive */
@media (max-width: 980px) {
  .hero { grid-template-columns: 1fr; }
  .feature { grid-column: span 12; }
  .feature { grid-template-columns: 1fr; }
  .feature .media { min-height: 220px; }
  .menu-layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; top: auto; }
  .item-grid { grid-template-columns: repeat(2, 1fr); }
  .locator-layout { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .nav { display: none; }
  .hero-media { min-height: 260px; }
  .banner-inner { grid-template-columns: 1fr; }
  .item-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-head { cursor: pointer; }
  .footer-head .chev { display: inline-flex; }
  .footer-links { display: none; }
  .footer-section[data-open="true"] .footer-links { display: grid; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .btn:hover { transform: none; }
  .carousel-track { transition: none; }
}
